<script setup lang="ts">import { reactive } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; const form=reactive({email:'lin@example.com',password:'password'}); const auth=useAuthStore(); const router=useRouter(); function submit(){auth.login(form.email);router.push('/portal')}</script>
<template><main class="portal-login"><section class="portal-login-panel"><div class="portal-brand portal-brand--dark"><span class="brand-mark">C</span>Cyberboard</div><p class="eyebrow">USER PORTAL</p><h1>登录用户中心</h1><p>查看套餐、订阅链接和流量使用情况。</p><form @submit.prevent="submit"><label>邮箱<input v-model="form.email" type="email" required /></label><label>密码<input v-model="form.password" type="password" required /></label><button class="primary-button" type="submit">登录</button></form><small>当前为前端占位登录。</small></section></main></template>
